// Config — настройки. Меняйте значения справа от двоеточия.
return [{ json: {
  "timezone": "Europe/Kyiv",
  "locale": "ru-RU",
  "sheets_api_base": "https://sheets.googleapis.com/v4",
  "spreadsheet_id": "REPLACE_WITH_SPREADSHEET_ID",
  "sheet_name": "Leads",
  "notify_chat_id": "REPLACE_WITH_CHAT_ID",
  "hot_chat_id": "",
  "working_hours": {
    "mon": {
      "open": "09:00",
      "close": "19:00"
    },
    "tue": {
      "open": "09:00",
      "close": "19:00"
    },
    "wed": {
      "open": "09:00",
      "close": "19:00"
    },
    "thu": {
      "open": "09:00",
      "close": "19:00"
    },
    "fri": {
      "open": "09:00",
      "close": "19:00"
    }
  },
  "sla": {
    "first_reminder_minutes": 15,
    "escalate_minutes": 60,
    "escalate_chat_id": ""
  }
} }];

// Find Overdue — leads nobody has taken. Status stays "new" until a manager changes it in the sheet.
const cfg = $('Config').first().json;
// ---- shared helpers ----
const MIN = 60000;
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
const digitsOf = (value) => String(value || '').replace(/[^\d]/g, '');
// Phones are stored in one international form, so the same person is recognised however they typed it.
function phoneOf(value) {
  const rules = cfg.phone || {};
  let d = digitsOf(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {
    d = rules.country_code + d.slice(rules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
}
function emailOf(value) {
  const e = String(value || '').trim().toLowerCase();
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/.test(e) ? e : '';
}
const localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {
  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
}).format(new Date(ms));
function localParts(ms) {
  const parts = {};
  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };
}
const sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;
const quoteSheet = (name) => "'" + String(name).replace(/'/g, "''") + "'";
// Column order of the Leads sheet. The sheet may start empty: the header is written with the first lead.
const COLUMNS = ['id', 'created_at', 'source', 'form', 'name', 'phone', 'email', 'message', 'utm_source', 'utm_medium', 'utm_campaign', 'page',
  'score', 'intent', 'summary', 'status', 'owner', 'touches', 'last_touch_at', 'reminded_level', 'notes'];
const colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const LAST = colLetter(COLUMNS.length - 1);
const rows = $input.first().json.values || [];
const now = nowMs();
const sla = cfg.sla || {};
const here = localParts(now);
const day = (cfg.working_hours || {})[here.weekday];
const minutes = here.hour * 60 + here.minute;
const toMin = (t) => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };
// Outside working hours nobody can act on a reminder, so none is sent; overdue leads come up in the morning.
if (!day || minutes < toMin(day.open) || minutes >= toMin(day.close)) return [{ json: { send: false, reason: 'outside_hours' } }];
if (!rows.length || rows[0][0] !== 'id') return [{ json: { send: false, reason: 'empty_sheet' } }];

const at = (row, c) => row[COLUMNS.indexOf(c)] || '';
const levelCol = colLetter(COLUMNS.indexOf('reminded_level'));
const first = [], second = [], updates = [];
rows.slice(1).forEach((row, i) => {
  if (at(row, 'status') !== 'new') return;
  const since = Date.parse(at(row, 'last_touch_at') || at(row, 'created_at'));
  if (isNaN(since)) return;
  const waited = Math.round((now - since) / MIN);
  const level = Number(at(row, 'reminded_level') || 0);
  const entry = { id: at(row, 'id'), name: at(row, 'name') || '—', contact: at(row, 'phone') || at(row, 'email'), score: at(row, 'score'), waited, owner: at(row, 'owner') };
  if (waited >= (sla.escalate_minutes || 60) && level < 2) { second.push(entry); updates.push({ range: `${quoteSheet(cfg.sheet_name)}!${levelCol}${i + 2}`, values: [['2']] }); }
  else if (waited >= (sla.first_reminder_minutes || 15) && level < 1) { first.push(entry); updates.push({ range: `${quoteSheet(cfg.sheet_name)}!${levelCol}${i + 2}`, values: [['1']] }); }
});
if (!updates.length) return [{ json: { send: false, reason: 'nothing_overdue' } }];

const fmt = (e) => `• ${e.name}, ${e.contact}, ${e.score}/5 — ждёт ${e.waited >= 120 ? Math.round(e.waited / 60) + ' ч' : e.waited + ' мин'}${e.owner ? ', ' + e.owner : ''} (${e.id})`;
const messages = [];
if (first.length) messages.push({ chat_id: cfg.notify_chat_id, text: [`Заявки без ответа: ${first.length}`, ...first.map(fmt), 'Поменяйте статус в таблице, когда свяжетесь.'].join('\n') });
if (second.length) messages.push({ chat_id: sla.escalate_chat_id || cfg.hot_chat_id || cfg.notify_chat_id, text: [`Заявки без ответа больше ${sla.escalate_minutes || 60} мин: ${second.length}`, ...second.map(fmt)].join('\n') });
return messages.map((m, i) => ({ json: Object.assign({ send: true }, m, i === 0 ? { http: { method: 'POST', url: `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchUpdate`, body: { valueInputOption: 'RAW', data: updates } } } : {}) }));
